from solution import tuple_int_str


def test_issue_example():
    """Convert a tuple of string values to a tuple of integer values: issue example."""
    assert tuple_int_str((('333', '33'), ('1416', '55'))) == ((333, 33), (1416, 55))  # int('333')=333, int('33')=33, int('1416')=1416, int('55')=55


def test_issue_single_pair():
    """Convert a tuple of string values to a tuple of integer values with one inner pair."""
    assert tuple_int_str((('1', '2'),)) == ((1, 2),)  # int('1')=1, int('2')=2


def test_issue_three_outer_pairs():
    """Convert a tuple of string values to a tuple of integer values with three outer tuples."""
    assert tuple_int_str((('1', '2'), ('3', '4'), ('5', '6'))) == ((1, 2), (3, 4), (5, 6))  # int('1')=1, int('2')=2, int('3')=3, int('4')=4, int('5')=5, int('6')=6


def test_issue_varying_inner_lengths():
    """Convert a tuple of string values to a tuple of integer values with inner lengths 3 and 1."""
    assert tuple_int_str((('1', '2', '3'), ('4',))) == ((1, 2, 3), (4,))  # int('1')=1, int('2')=2, int('3')=3, int('4')=4


def test_issue_empty_outer():
    """Convert a tuple of string values to a tuple of integer values with empty outer tuple."""
    assert tuple_int_str(()) == ()  # len(())==0 so len(expected)==0


def test_issue_empty_inner():
    """Convert a tuple of string values to a tuple of integer values with one empty inner tuple."""
    assert tuple_int_str(((),)) == ((),)  # len(())==0 so len(expected[0])==0


def test_issue_zero_strings():
    """Convert a tuple of string values to a tuple of integer values for zero boundary."""
    assert tuple_int_str((('0', '0'),)) == ((0, 0),)  # int('0')=0, int('0')=0


def test_issue_leading_zeros():
    """Convert a tuple of string values to a tuple of integer values with leading zeros."""
    assert tuple_int_str((('007', '010'),)) == ((7, 10),)  # int('007')=7, int('010')=10


def test_issue_negative_strings():
    """Convert a tuple of string values to a tuple of integer values with negative values."""
    assert tuple_int_str((('-1', '-20'),)) == ((-1, -20),)  # int('-1')=-1, int('-20')=-20


def test_contract_outer_is_tuple():
    """Documented rule 'to a tuple of integer values' requires the outer container to be a tuple."""
    assert tuple_int_str((('11', '22'),)) == ((11, 22),)  # int('11')=11, int('22')=22


def test_contract_inner_is_tuple():
    """Documented rule 'to a tuple of integer values' requires inner containers to stay tuples."""
    assert tuple_int_str((('13', '14'),)) == ((13, 14),)  # int('13')=13, int('14')=14


def test_contract_elements_are_ints():
    """Documented rule 'to a tuple of integer values' requires elements to be integers in order."""
    assert tuple_int_str((('15', '16'), ('18', '17'))) == ((15, 16), (18, 17))  # int('15')=15, int('16')=16, int('18')=18, int('17')=17
